MAP_SP = register('walk.map', 'Big ideas of a walk', 'How the tutor finds the claim and the 3 to 7 big ideas of a source for a walk. The other ideas stay on the steps as reading.', """You plan what a learner must understand from one source.
- `claim` is the one thing that the source shows, in one sentence.
- Give 3 to 7 big ideas that a novice must understand to explain the claim. Give each by its number in the list.
- A big idea is a mechanism, a reason or a method. A number, a year, a score, an ablation, a result table, a remark of the author or a history line is never a big idea. A result is a big idea only when it is the claim.
- `understanding` says the idea as "X does Y because Z": what it does and why. No sizes, years or scores, unless the number is the idea.
- `question` is one essential question that the idea answers, for example "Why can attention look at all the words at once?".
- `wrong` lists 1 to 3 common wrong ideas about it: {"think": the wrong idea, "fact": what is true}.
- `details` gives the numbers of the other ideas in the list that support this idea. Put each other idea under one big idea.
- When the prompt says who the walk is for, write each `understanding` and `question` in words that they know.""")

def map_prompt(cs, most:int, audience:str='') -> str:
    """The prompt that asks for the claim and the `most` big ideas of the concepts `cs`, numbered from 1 in the order of the source. A detail is marked.
    `audience` says who the walk is for; it goes in a `<source>` marker, as data and not as instructions."""
    ls = '\n'.join(f"{k}. {c.get('name')}{' [detail]' if c.get('detail') else ''}: {c.get('core') or c.get('statement', '')}" for k, c in enumerate(cs, 1))
    return (f"Ideas, in the order of the source:\n{ls}\n\n" + (f"Who the walk is for:\n{fence('audience', audience)}\n" if audience.strip() else '') + f"Give 3 to {most} big ideas. "
            'Return JSON: {"claim": str, "ideas": [{"n": int, "understanding": str, "question": str, "wrong": [{"think": str, "fact": str}], "details": [int]}]}')

def _core(t) -> str:
    "The understanding `t` as a core: one line, without a leading 'You understand that'."
    return re.sub(r'^you understand that\s+', '', ' '.join(str(t or '').split()), flags=re.I)

def walk_map(lr:Learning, ask, steps:list, most:int=None, audience:str='') -> tuple:
    """`(steps, more, map)` for the steps of a source: the big ideas of the map, in source order, each with its essential `question` and its
    `details`, the slugs of the other steps, and the map (`claim` and `ideas`). Each big idea saves its core and its wrong ideas on its concept.
    With fewer than 3 steps there is no map. When the reply has no valid idea, `main_steps` picks the steps and the map is None. `audience` goes to the map prompt."""
    most = min(most or val('walks.steps'), 7)
    if len(steps) < 3: return steps, [], None
    cs = [lr.concept(s['slug']) or AttrDict(name=s['slug']) for s in steps]
    try: r = ask_json(for_task(ask, 'pick'), map_prompt(cs, most, audience), prompt('walk.map'), need=('claim',))
    except ValueError: r = {}
    ideas = [x for x in (r.get('ideas') if isinstance(r, dict) and isinstance(r.get('ideas'), list) else ()) if isinstance(x, dict) and type(x.get('n')) is int and 1 <= x['n'] <= len(steps)]
    ideas = sorted({x['n']: x for x in ideas}.values(), key=lambda x: x['n'])[:most]
    if not ideas: return (*main_steps(lr, ask, steps, most), None)
    big = {x['n'] for x in ideas}
    out, mp = [], dict(claim=' '.join(str(r.get('claim')).split()), ideas=[])
    for x in ideas:
        s, ws = steps[x['n'] - 1], wrong_ideas(x['wrong'] if isinstance(x.get('wrong'), list) else ())
        dts = [steps[k - 1]['slug'] for k in dict.fromkeys(x.get('details') or ()) if type(k) is int and 1 <= k <= len(steps) and k not in big]
        if (core := _core(x.get('understanding'))): lr.update(s['slug'], core=core, **({'wrong': ws} if ws else {}))
        q = ' '.join(str(x.get('question') or '').split())
        out.append({**s, 'question': q, 'details': dts})
        mp['ideas'].append(dict(slug=s['slug'], understanding=core, question=q, wrong=ws, details=dts))
    keep = {s['slug'] for s in out}
    return out, [s['slug'] for s in steps if s['slug'] not in keep], mp

# %% ../nbs/04_path.ipynb #mx13
def hands_most(n:int) -> int:
    "The most hands-on checks in a walk of `n` steps: the share `walks.hands` of them, rounded down, and at least 1 from 3 steps when the share is not 0."
    share = val('walks.hands')
    k = math.floor(n * share + 1e-9)
    return max(k, 1) if n >= 3 and share else k

def cap_hands(lr:Learning, steps:list, tool:bool=False) -> list:
    """`steps` with at most `hands_most` hands-on checks, the first ones in walk order. Each later step gets a check in its text ways.
    A step that the plan marks `hands='notebook'` builds the goal: it stays as it is, and it does not count."""
    most, n = hands_most(len(steps)), 0
    for s in steps:
        if s.get('hands') == 'notebook' or (s.get('check') or {}).get('kind', 'short') == 'short': continue
        n += 1
        if n > most: s['check'] = _check(lr, lr.concept(s['slug']) or AttrDict(slug=s['slug']), tool, hands=False)
    return steps

def builds_goal(s) -> bool:
    "Whether step `s` is a notebook that builds the goal: the plan marks it `hands='notebook'`, or its check says so."
    return s.get('hands') == 'notebook' or (s.get('check') or {}).get('why') == GOAL_WHY

def hands_count(steps) -> tuple:
    "`(hands-on checks, steps not skipped, notebooks that build the goal)` of `steps`. A notebook that builds the goal is not a hands-on check. A skipped step does not count."
    ss = [s for s in steps if s.get('status') != 'skip']
    goal = [builds_goal(s) for s in ss]
    return sum((s.get('check') or {}).get('kind', 'short') != 'short' and not g for s, g in zip(ss, goal)), len(ss), sum(goal)

# %% ../nbs/04_path.ipynb #w304
def _leela(c, tool:bool) -> dict:
    "`leela=True` for an idea with a code way on a tool walk: its code is learned in Leela."
    return dict(leela=True) if tool and 'code' in (c.get('ways') or ()) else {}

def _subject_of(lr:Learning, slugs, subject:str='') -> str:
    "`subject`, or the most common subject of the concepts `slugs` when it is empty."
    ss = [c.subject for c in map(lr.concept, slugs) if c and c.subject]
    return subject or (max(set(ss), key=ss.count) if ss else '')

def _fill_subject(lr:Learning, slugs, subject:str='') -> str:
    "Give the subject of a walk (`subject`, or the most common one of its concepts) to each of its concepts that has none. A concept that you moved by hand stays. Return the subject."
    sub = _subject_of(lr, slugs, subject)
    for s in slugs if sub else ():
        if (c := lr.concept(s)) and not c.subject: lr.set_subject(s, sub)
    return sub

def _steps(lr:Learning, slugs, doc_id:str, shelf:str, title:str, tool:bool=False, no_code:bool=False) -> list:
    "One walk step for each of `slugs` that has a place in document `doc_id`, in the order of the document. On a tool walk, an idea with a code way has `leela`. With `no_code`, no check is code and no idea goes to Leela."
    cs = sorted(((c, placement(c, doc_id)) for c in map(lr.concept, slugs) if c and placement(c, doc_id)), key=lambda x: x[1].get('order') or 0)
    return [dict(slug=c.slug, status='known' if learned(c) else 'todo', why='',
                 read=dict(shelf=shelf, doc_id=doc_id, title=title, section=p.get('section') or '',
                           page=p.get('page'), span=p.get('span'), text=p.get('passage') or '', figure=p.get('figure')),
                 check=_check(lr, c, tool, no_code=no_code), **({} if no_code else _leela(c, tool))) for c, p in cs]

def _save_walk(lr:Learning, ask, jid:str, title:str, steps:list, source:dict|None, goal:str, subject:str, tool:bool=False, audience:str='', no_code:bool=False, **extra) -> AttrDict:
    """Save a walk that is not started yet, with the big ideas of its map only (`walk_map`) and its share of hands-on checks (`cap_hands`). `tool` marks a library or a command-line tool. The map goes on the walk.
    `audience` goes to the map, and the walk keeps it and `no_code`."""
    steps, more, mp = walk_map(lr, ask, steps, audience=audience)
    if mp: extra = {**extra, 'map': mp}
    extra = {**extra, **({'audience': audience.strip()} if audience.strip() else {}), **({'no_code': True} if no_code else {})}
    steps = cap_hands(lr, steps, tool)
    return lr.put_journey(dict(id=jid, title=title, goal=goal, subject=subject, steps=steps, created=time.time(),
                               mode='walk', source=source, started=None, sitting=None, tool=tool, more=more, **extra))

def _walk(lr:Learning, ask, jid:str, title:str, slugs, doc_id:str, source:dict|None, goal:str, subject:str, tool:bool=False) -> AttrDict:
    "Save a walk with one step for each of `slugs` that has a place in document `doc_id`, in the order of the document."
    return _save_walk(lr, ask, jid, title, _steps(lr, slugs, doc_id, (source or {}).get('shelf', 'store'), title, tool), source, goal, subject, tool)

def journey_from_source(lr:Learning, ask, ref:str, shelf:str='store', subject:str='', tool:bool=False) -> AttrDict:
    "Make a walk from one vault document, by doc id, source or title. A notebook of yours becomes a `notebook_walk`. `tool` marks a library or a command-line tool."
    d, subject = doc_pages(lr, ref, shelf), clean_subject(subject)
    if (f := nb_file(lr, d.doc_id, shelf)): return notebook_walk(lr, d, *f, subject, tool, ask=ask)   # one of your notebooks: used as it is
    slugs = from_vault(lr, ask, d.doc_id, subject, shelf)
    return _walk(lr, ask, _new_id(d.title), d.title, slugs, d.doc_id, dict(shelf=shelf, doc_id=d.doc_id, title=d.title), f'Read {d.title}', _fill_subject(lr, slugs, subject), tool)

# %% ../nbs/04_path.ipynb #w306
def journey_from_text(lr:Learning, ask, text:str, title:str, subject:str='', tool:bool=False) -> AttrDict:
    "Make a walk from pasted `text`."
    jid, subject = _new_id(title), clean_subject(subject)
    slugs = extract(lr, ask, subject=subject, source=dict(src='text', doc_id=jid, title=title), pages=[(None, text)])
    return _walk(lr, ask, jid, title, slugs, jid, None, f'Read {title}', _fill_subject(lr, slugs, subject), tool)

# %% ../nbs/04_path.ipynb #nbw02
NB_SECTION_MOST = 8000   # the most characters of the passage of one section: whole cells, in order, until the next cell would pass it
NB_PICTURE = re.compile(r'(\bshow_images?|\bimshow|\bplt\.\w+|\.plot|\bplot_\w+)\(')   # a call that draws: a demo helps the idea of that section. An import does not count
NB_WHY_DEMO = 'the notebook draws a picture here, so a demo helps'

def nb_file(lr:Learning, doc_id:str, shelf:str='store') -> tuple|None:
    "`(shelf, path)` of the notebook file of vault document `doc_id`, when the document is a notebook that is on this Mac; else None."
    for name in dict.fromkeys([shelf, *lr.vault.shelf_names()]):
        if name == SHELF or (sh := lr.doc_shelf(name)) is None or not (r := first(sh.t.docs(where='id=?', where_args=[doc_id]))): continue
        p = str(meta_of(r).get('path') or '')
        return (name, p) if p.endswith('.ipynb') and Path(p).is_file() else None
    return None

def _head(src:str) -> tuple:
    "`(level, text)` of the heading on the first line of markdown `src`, or `(0, '')`."
    m = re.match(r'(#{1,6})\s+(.+)', (src or '').lstrip())
    return (len(m[1]), m[2].strip().strip('#').strip()) if m else (0, '')

def nb_sections(cells) -> list:
    """The sections of a notebook with the cells `cells`, in order, as `AttrDict(head, first, last)` (the places of its first and last cell).
    A markdown cell that starts with a heading of the section level starts a section. The section level is the top level of the headings
    after the title (one `#` heading at the top). The cells before the first section are not a section."""
    hs = [(k, *_head(c.source)) for k, c in enumerate(cells) if c.cell_type == 'markdown' and _head(c.source)[0]]
    if hs and hs[0][1] == 1 and sum(h[1] == 1 for h in hs) == 1: hs = hs[1:]   # the title
    if not hs: return []
    top = min(h[1] for h in hs)
    starts = [(k, t) for k, lv, t in hs if lv == top]
    return [AttrDict(head=t, first=k, last=(starts[n + 1][0] if n + 1 < len(starts) else len(cells)) - 1) for n, (k, t) in enumerate(starts)]

def nb_text(cells) -> str:
    "The words and the code of `cells` as one markdown text, word for word: each markdown cell as it is, each code cell in a ```python block, up to `NB_SECTION_MOST` characters of whole cells."
    out, n = [], 0
    for c in cells:
        t = c.source.strip() if c.cell_type == 'markdown' else f"```python\n{c.source.strip()}\n```" if c.source.strip() else ''
        if not t: continue
        if out and n + len(t) > NB_SECTION_MOST: break
        out.append(t); n += len(t) + 2
    return '\n\n'.join(out)

def _first_words(cells, head) -> str:
    "The first sentence of prose in `cells` after the heading `head`, word for word: the statement of the idea of a section."
    for c in cells:
        if c.cell_type != 'markdown': continue
        for para in re.split(r'\n\s*\n', c.source):
            t = ' '.join(para.split())
            if t.startswith('#') or len(t) < 30: continue
            return re.split(r'(?<=[.!?])\s', t, maxsplit=1)[0]
    return head

def notebook_walk(lr:Learning, d, shelf:str, path:str, subject:str='', tool:bool=False, ask=None) -> AttrDict:
    """A walk from one of your notebooks, used as it is: one idea for each section, named by its heading. The passage of the idea is the
    words and the code of the section, word for word, with its source. The tutor adds only the check of each idea: a demo where the code
    of the section draws a picture, else a check in the ways of the idea, with the share of hands-on checks (`cap_hands`) for these. With `ask` and
    three sections or more, the walk map keeps the sections that teach a big idea (one model call); a setup section stays in the notebook only."""
    nb = read_nb(path)
    stem, subject = slugify(Path(path).stem), clean_subject(subject)
    steps = []
    for sec in nb_sections(nb.cells):
        cells = nb.cells[sec.first:sec.last + 1]
        slug = slugify(f'{stem} {sec.head}')
        if not slug or any(s['slug'] == slug for s in steps) or not idea_name(sec.head): continue
        c = lr.put(sec.head, _first_words(cells, sec.head), subject, slug=slug, provenance=[dict(src=f'vault:{shelf}', doc_id=d.doc_id, at=time.time())])
        demo = bool(NB_PICTURE.search('\n'.join(x.source for x in cells if x.cell_type == 'code')))
        ck = AttrDict(way='demo', kind='demo', depth=DEPTH['demo'], why=NB_WHY_DEMO) if demo else _check(lr, c, tool)
        steps.append(dict(slug=c.slug, status='known' if learned(c) else 'todo', why='',
                          read=dict(src=f'vault:{shelf}', shelf=shelf, doc_id=d.doc_id, ref=d.doc_id, title=d.title, section=sec.head, page=None, figure=None,
                                    text=nb_text(cells), cells=[sec.first, sec.last]),
                          check=ck, **_leela(c, tool)))
    big, more, mp = walk_map(lr, ask, steps) if ask is not None and len(steps) >= 3 else (steps, [], None)
    if not mp: big, more = steps, []   # no map: each section stays an idea
    steps = big
    cap_hands(lr, [s for s in steps if s['check'].get('why') != NB_WHY_DEMO], tool)   # a demo where the notebook draws stays; the share counts the other checks
    return lr.put_journey(dict(id=_new_id(d.title), title=d.title, goal=f'Read {d.title}', subject=_fill_subject(lr, [s['slug'] for s in steps], subject), steps=steps,
                               created=time.time(), mode='walk', source=dict(shelf=shelf, doc_id=d.doc_id, title=d.title), started=None, sitting=None, tool=tool, more=more,
                               notebook=dict(path=path), **({'map': mp} if mp else {})))


# %% ../nbs/04_path.ipynb #nbw08
from fastcore.nbio import mk_cell, write_nb
from .contract import COPY_DIR

def copy_path(assets, j) -> Path:
    "The path of the learning copy of the notebook of walk `j`: `<assets>/walks/<walk id>/<name of the notebook>`, in the folder of the walk."
    return Path(assets).resolve()/COPY_DIR/j['id']/Path(j['notebook']['path']).name

def learning_copy(j, dest, demos=None) -> Path:
    """Write the learning copy of the notebook of walk `j` to `dest`: the notebook as it is, with the demo of each idea (`demos` maps a slug
    to a rupaka spec) as a markdown cell with a ```rupaka block after the last cell of its section. Leela draws the block. The learner's
    own notebook is only read, never written. Return `dest`."""
    from rupaka.render import md as rk_md   # rupaka loads only when a copy is written
    src, dest = Path(j['notebook']['path']), Path(dest)
    if dest.resolve() == src.resolve(): raise ValueError('The learning copy cannot be your own notebook.')
    nb = read_nb(src)
    after = {}
    for s in j['steps']:
        if (spec := (demos or {}).get(s['slug'])) and isinstance(k := ((s.get('read') or {}).get('cells') or [None, None])[1], int):
            name = (s.get('read') or {}).get('section') or s['slug']
            after.setdefault(k, []).append(mk_cell(f"**A demo: {name}.** Predict first, then move the parts.\n\n{rk_md(spec)}", 'markdown'))
    cells = []
    for k, c in enumerate(nb.cells): cells += [c, *after.get(k, ())]
    nb.cells = cells
    nb.metadata = {**nb.metadata, 'abhyasa': dict(walk=j['id'], copy_of=str(src))}
    dest.parent.mkdir(parents=True, exist_ok=True)
    write_nb(nb, dest)
    return dest


# %% ../nbs/04_path.ipynb #lk41
def journey_from_sources(lr:Learning, ask, docs:list, title:str='', subject:str='', progress=None, tool:bool=False, audience:str='', no_code:bool=False, **extra) -> AttrDict:
    """Make one walk across the vault documents `docs`, each with `shelf`, `doc_id`, `title` and `url`, in their order. `extra` goes on the walk.
    `audience` (who the walk is for) goes to the walk map; with `no_code`, no check is code. The walk keeps both."""
    if not docs: raise ValueError('no pages to walk')
    got, subject = {}, clean_subject(subject)
    for k, d in enumerate(docs):
        if progress: progress(k, len(docs))
        got[d.doc_id] = from_vault(lr, ask, d.doc_id, subject, d.shelf, chars=val('links.read'))
    told = lambda s, d: bool((placement(lr.concept(s) or {}, d.doc_id) or {}).get('passage'))
    named = lambda s: [d for d in docs if s in got[d.doc_id]]
    tx = {d.doc_id: bool(from_transcript(lr, d)) for d in docs}
    home = {s: (first(d for d in named(s) if told(s, d) and not tx[d.doc_id]) or first(d for d in named(s) if told(s, d)) or named(s)[0]).doc_id
            for d in docs for s in got[d.doc_id]}   # a notebook or a doc that tells the idea is its home before a lecture transcript
    steps = [x for d in docs for x in _steps(lr, [s for s in got[d.doc_id] if home[s] == d.doc_id], d.doc_id, d.shelf, d.title, tool, no_code)]
    title = title or docs[0].title
    return _save_walk(lr, ask, _new_id(title), title, steps, dict(url=docs[0].url, docs=[dict(d) for d in docs]), f'Read {title}', _fill_subject(lr, [s for v in got.values() for s in v], subject), tool, audience, no_code, **extra)

# %% ../nbs/04_path.ipynb #dt02
def data_row(path, note='', name='') -> dict:
    "The data folder `path` as a row `{path, note}` (and `name`, when given), with `~` for the home folder. A `ValueError` says in one line why abhyasa cannot use it."
    if name and not DATA_NAME.fullmatch(str(name)): raise ValueError(f'{str(name)[:40]} is not a data name, as EPISODES.')
    p = str(path or '').strip()
    if why := data_path_why(p): raise ValueError(f'abhyasa cannot use this folder: {why}.')
    q = Path(p).expanduser().resolve()
    if not q.is_dir(): raise ValueError('abhyasa finds no folder at this path.')
    return dict(path=f'~/{q.relative_to(Path.home().resolve())}', note=clip(' '.join(str(note or '').split()), 199), **({'name': name} if name else {}))

def keep_data(rows, path, note='', name='') -> list:
    "`rows` with the data folder `path`, its `note` and its data `name` at the end, one time for each path and each name. A `ValueError` says why abhyasa cannot add it."
    r = data_row(path, note, name)
    rows = [d for d in rows or () if d['path'] != r['path'] and not (name and d.get('name') == name)]
    if len(rows) >= DATA_MOST: raise ValueError(f'You can keep at most {DATA_MOST} data folders.')
    return [*rows, r]

def folder_list(path, most:int=10) -> str:
    "The names of the first `most` entries of folder `path` that do not start with a dot, and how many more. '' when abhyasa cannot read it."
    try: xs = sorted(p.name + '/' * p.is_dir() for p in Path(path).expanduser().iterdir() if not p.name.startswith('.'))
    except OSError: return ''
    return ', '.join(xs[:most]) + (f' and {len(xs) - most} more' if len(xs) > most else '')

def _one_line(s) -> str: return ''.join(ch for ch in ' '.join(str(s).split()) if ch.isprintable())

def with_stop(s) -> str:
    "`s` as one line that ends with a stop: a text that ends with `.`, `!` or `?` gets no second stop. '' stays ''."
    s = _one_line(s).rstrip()
    return s if not s or s[-1] in '.!?' else s + '.'

def data_entries(rows, taken=()) -> list:
    """The data folders `rows` as data entries `{name, path, what, need}` of a notebook spec. A row with a `name` keeps it. Each other name is new:
    not in `taken`, and not used twice."""
    rows, out, used = list(rows or ())[:DATA_MOST], [], set(taken)
    named = {d['name'] for d in rows if DATA_NAME.fullmatch(str(d.get('name') or ''))} - used
    used |= named
    for d in rows:
        if (name := d.get('name')) not in named:
            base = re.sub(r'[^A-Z0-9]+', '_', Path(d['path']).name.upper()).strip('_') or 'DATA'
            base, k = (base if base[0].isalpha() else f'D_{base}')[:36], 2
            name = base
            while name in used: name, k = f'{base}_{k}', k + 1
            used.add(name)
        ls = folder_list(d['path'])
        what = ' '.join(x for x in (with_stop(d.get('note')) or 'Your data folder.', f'It holds: {ls}.' if ls else '') if x)
        out.append(dict(name=name, path=d['path'], what=clip(what, 199), need=False))
    return out

def _own(e, by) -> dict:
    "Data entry `e` on your folders `by` (by name and by path): the name and path of its folder, else no path and `need`."
    o = by.get(e.get('name') if isinstance(e.get('name'), str) else '') or by.get(e.get('path') if isinstance(e.get('path'), str) else '')
    return {**e, 'name': o['name'], 'path': o['path'], 'what': e.get('what') or o['what'], 'need': False} if o else {**e, 'path': '', 'need': True}

def with_data(entries, rows) -> list:
    """The data entries `entries` on your data folders `rows` only, then an entry for each folder that they do not name, at most `DATA_MOST` in all.
    An entry with the name or the path of a folder gets that folder. Any other entry has no path and `need`: the learner adds its folder."""
    own = data_entries(rows)
    by = {**{o['path']: o for o in own}, **{o['name']: o for o in own}}
    out, used = [], set()
    for e in entries if isinstance(entries, (list, tuple)) else ():
        if isinstance(e, dict) and (e := _own(e, by)).get('name') in used: continue
        if isinstance(e, dict): used.add(e.get('name'))
        out.append(e)
    return [*out, *[o for o in own if o['name'] not in used]][:DATA_MOST]

